import pixeltable as px

@px.udf()
def word_count(text: str) -> int:
    """Count the number of words in text."""
    if not text:
        return 0
    return len(text.split())

docs = px.get_table('docs')
docs.add_column(n_words=word_count(docs.content), allow_overwrite=True)

